int dtc_fm_encode(const uint8_t*in,size_t n,uint16_t*out){size_t i,j;uint16_t w;if(!in||!out)return-1;for(i=0;i<n;i++){w=0;for(j=0;j<8;j++)w=(uint16_t)((w<<2)|2|((in[i]>>(7-j))&1));out[i]=w;}return 0;}
int dtc_fm_decode(const uint16_t*in,size_t n,uint8_t*out,size_t*bad){size_t i,j,e=0;uint8_t v;uint16_t w;if(!in||!out)return-1;for(i=0;i<n;i++){w=in[i];v=0;for(j=0;j<8;j++){unsigned pair=(w>>(14-2*j))&3;if((pair&2)==0)e++;v=(uint8_t)((v<<1)|(pair&1));}out[i]=v;}if(bad)*bad=e;return 0;}
int dtc_mfm_encode(const uint8_t*in,size_t n,uint16_t*out,unsigned*prev){size_t i,j;unsigned p=prev?(*prev&1):0;for(i=0;i<n;i++){uint16_t w=0;for(j=0;j<8;j++){unsigned d=(in[i]>>(7-j))&1,c=(!p&&!d);w=(uint16_t)((w<<2)|(c<<1)|d);p=d;}out[i]=w;}if(prev)*prev=p;return 0;}
int dtc_mfm_decode(const uint16_t*in,size_t n,uint8_t*out,size_t*bad,size_t*viol){size_t i,j,e=0,vio=0;unsigned prev=0;for(i=0;i<n;i++){uint8_t v=0;for(j=0;j<8;j++){unsigned pair=(in[i]>>(14-2*j))&3,c=pair>>1,d=pair&1,expect=(!prev&&!d);e+=c!=expect;vio+=(prev&&d);v=(uint8_t)((v<<1)|d);prev=d;}out[i]=v;}if(bad)*bad=e;if(viol)*viol=vio;return 0;}
int dtc_gcr_encode(const uint8_t*in,size_t n,const uint8_t*t,unsigned bits,uint8_t*out,size_t*outbits){size_t i,p=0;unsigned mask=(1u<<bits)-1;if(!in||!t||!out||bits>8)return-1;memset(out,0,(n*8*bits/4+7)/8);for(i=0;i<n;i++){unsigned q[2]={in[i]>>4,in[i]&15};for(unsigned k=0;k<2;k++)for(int b=bits-1;b>=0;b--,p++)if((t[q[k]]>>b)&1)out[p>>3]|=(uint8_t)(0x80u>>(p&7));}if(outbits)*outbits=p;(void)mask;return 0;}
int dtc_gcr_decode(const uint8_t*in,size_t inbits,const uint8_t*t,unsigned bits,uint8_t*out,size_t*outn){size_t p=0,o=0;int half=-1;if(!in||!t||!out||!bits)return-1;while(p+bits<=inbits){unsigned code=0,k,b;for(b=0;b<bits;b++,p++)code=(code<<1)|((in[p>>3]>>(7-(p&7)))&1);for(k=0;k<16&&t[k]!=code;k++);if(k==16)return-2;if(half<0)half=(int)k;else{out[o++]=(uint8_t)((half<<4)|k);half=-1;}}if(outn)*outn=o;return half<0?0:-3;}

